<?php
declare(strict_types=1);
if(!defined('CWP_BOOT')){http_response_code(404);exit;}
require_once CWP_CODE_ROOT.'/app/providers/directory_listing_controls.php';
function provider_directory_indexing_controls_label(string $status):string {return match($status){'observed'=>'Requested setting reported after the request','not_sent'=>'Request was not sent','interrupted'=>'Request interrupted — review required',default=>'Change requested — result not yet confirmed'};}
function provider_directory_indexing_controls_admin_render():void {
    provider_settings_manager();echo '<section class="workspace-card" id="directory-listing-changes"><h2>Change directory listing</h2><p>Enabling directory listing can show a file list instead of an index page. Choose a setting for an assigned website, then check what the provider reports. A matching setting does not prove this request caused the change or show which files visitors can access. Client sharing stays separate.</p>';
    try{
        if(!provider_directory_indexing_ready()||!provider_operations_ready()){echo '<p>Set up directory listing observations and provider operations first.</p></section>';return;}
        if(!provider_directory_indexing_controls_ready()){echo '<form method="post" data-directory-listing-control-prepare>';admin_action('provider_directory_indexing_control_prepare');admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">Set up directory listing changes</button></form></section>';return;}
        $page=max(1,min(10000,(int)($_GET['directory_indexing_control_page']??1)));$links=all('SELECT l.id,l.profile_id,l.package_id,c.name AS client_name FROM '.table('provider_package_links').' l JOIN '.table('studio_clients').' c ON c.id=l.client_id ORDER BY l.id LIMIT 20 OFFSET '.(($page-1)*20));
        foreach($links as $link){echo '<article class="workspace-card" data-directory-listing-control-package><h3>'.esc($link['client_name']).' · Package '.esc((string)$link['package_id']).'</h3>';
            try{$form=staff_locked(fn()=>staff_transaction(function()use($link):array{if(!provider_directory_indexing_controls_ready())throw new RuntimeException('Directory listing change storage is unavailable.');$pending=provider_directory_indexing_controls_pending($link['profile_id'],(int)$link['package_id']);$r=provider_directory_indexing_latest($link['id']);$binding=provider_directory_indexing_binding($link['id']);if(!$r)throw new RuntimeException('Save a Directory listing observation first.');[, $anchor]=provider_directory_indexing_controls_precondition($link['id'],$r['id'],$binding->sha256);return ['pending'=>$pending,'binding'=>$binding,'anchor'=>$anchor];}));
                if($form['pending'])echo '<p>A prior request for this package remains unresolved. Use its history below; another change cannot be sent.</p>';
                else{$desired=!$form['anchor']['value'];echo '<form method="post" data-directory-listing-control-change>';admin_action('provider_directory_indexing_control_change');foreach(['request_id'=>bin2hex(random_bytes(16)),'link_id'=>$link['id'],'anchor_id'=>$form['anchor']['id'],'binding_sha256'=>$form['binding']->sha256,'desired'=>$desired?'true':'false'] as $name=>$value)echo '<input type="hidden" name="'.$name.'" value="'.esc($value).'">';echo '<p>Latest saved setting: <strong>'.($form['anchor']['value']?'Enabled':'Disabled').'</strong>. Requested setting: <strong>'.($desired?'Enabled':'Disabled').'</strong>.</p><label class="check"><input type="checkbox" name="reviewed" value="1" required> I reviewed this website and approve this one request.</label>';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">'.($desired?'Enable directory listing':'Disable directory listing').'</button></form>';}
            }catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="hint">'.esc($e->getMessage()).'</p>';}echo '</article>';
        }
        echo '<nav class="button-row" aria-label="Directory listing change assignments">';if($page>1)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['directory_indexing_control_page'=>$page-1])).'#directory-listing-changes">Previous assignments</a>';if(count($links)===20&&$page<10000)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['directory_indexing_control_page'=>$page+1])).'#directory-listing-changes">More assignments</a>';echo '</nav>';
        $historyPage=max(1,min(10000,(int)($_GET['directory_indexing_change_history_page']??1)));echo '<h3>Change request history</h3>';
        foreach(all('SELECT id FROM '.table('provider_directory_changes').' ORDER BY grant_seq DESC LIMIT 20 OFFSET '.(($historyPage-1)*20)) as $row){$view=staff_locked(fn()=>staff_transaction(fn()=>provider_directory_indexing_controls_summary($row['id'])));echo '<article class="workspace-message" data-directory-listing-control-history><h4>'.esc(provider_directory_indexing_controls_label($view['status'])).'</h4><p>Package '.esc((string)$view['package_id']).' · Requested setting: '.($view['requested_value']?'Enabled':'Disabled').' · '.esc(gmdate('Y-m-d H:i:s',$view['requested_epoch'])).' UTC</p>';
            if($view['status']==='interrupted'){
                echo '<p>Part of this request’s saved history is missing. The result remains unresolved, so another change cannot be sent.</p>';
                if($view['recovery_ledger_sha256']!==null){echo '<form method="post" data-directory-listing-control-recover>';admin_action('provider_directory_indexing_control_recover');echo '<input type="hidden" name="request_id" value="'.esc($view['id']).'"><input type="hidden" name="ledger_sha256" value="'.esc($view['recovery_ledger_sha256']).'"><p>The saved attempt allows the missing request history to be restored. After restoring it, check the current setting separately. Restoring history does not resend the change or confirm its result.</p><label class="check"><input type="checkbox" name="reviewed" value="1" required> I reviewed this request and want to restore its saved history.</label>';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn outline">Restore saved request history</button></form>';}
                else echo '<p>This request’s history cannot be safely restored here. Another change remains blocked. You can still check the reported directory listing setting in the observations section above.</p>';
            }
            elseif($view['status']==='not_sent')echo '<p>The change was not sent to the provider. Refresh the saved directory listing setting before approving a new request.</p>';
            elseif($view['status']==='observed')echo '<p>A later check reported the requested setting. This does not prove the request caused the change or show which files visitors can access.</p>';
            else{echo '<p>The result of this change is not yet confirmed. A failed check, an unavailable setting or a different setting does not allow the request to be sent again.</p>';if($view['last_check'])echo '<p>Last follow-up: '.esc($view['last_check']['disposition']==='different'?'a different setting was reported':'the setting was unavailable').'.</p>';if($view['current_assignment']){echo '<form method="post" data-directory-listing-control-verify>';admin_action('provider_directory_indexing_control_verify');echo '<input type="hidden" name="request_id" value="'.esc($view['id']).'">';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn outline">Check current setting</button><p class="hint">Checks the provider once, subject to the usual refresh limits. This does not resend the change.</p></form>';}}
            if($view['recovered_dispatch'])echo '<p data-directory-listing-control-recovered>The missing request history was restored. Restoring history did not resend the change or confirm its result.</p>';
            if(!$view['current_assignment'])echo '<p>The website assignment or provider account has changed. This request remains saved for review.</p>';echo '</article>';
        }
        echo '<nav class="button-row" aria-label="Directory listing change history">';if($historyPage>1)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['directory_indexing_change_history_page'=>$historyPage-1])).'#directory-listing-changes">Previous requests</a>';if((int)query('SELECT COUNT(*) FROM '.table('provider_directory_changes'))->fetchColumn()>$historyPage*20&&$historyPage<10000)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['directory_indexing_change_history_page'=>$historyPage+1])).'#directory-listing-changes">More requests</a>';echo '</nav>';
    }catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p>';}echo '</section>';
}
